// Stage a private npm candidate. Development continues to consume native TypeScript.
import { spawnSync } from "node:child_process";
import { chmodSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
const stage = join(root, ".sandbox/releases/sdk");
if (process.argv.length !== 2) {
  console.error("usage: npm run release:prepare");
  process.exit(2);
}
rmSync(stage, { recursive: true, force: true });
mkdirSync(stage, { recursive: true });
const build = spawnSync(join(root, "node_modules/.bin/tsc"), [
  "-p", join(root, "packages/sdk/tsconfig.release.json"), "--outDir", join(stage, "dist"),
], { stdio: "inherit" });
if (build.status !== 0) {
  console.error(build.error?.message ?? "release compilation failed");
  process.exit(build.status ?? 1);
}
const source = JSON.parse(readFileSync(join(root, "packages/sdk/package.json"), "utf8"));
const manifest = {
  name: source.name, version: source.version, private: true, type: "module",
  description: source.description, engines: { node: ">=22.18.0" },
  exports: { ".": { types: "./dist/src/index.d.ts", import: "./dist/src/index.js" } },
  types: "./dist/src/index.d.ts", files: ["dist"],
  bin: { "solanaut-replay": "./dist/bin/replay.js", "solanaut-pin-table": "./dist/bin/pin-table.js", "solanaut-verify-archive": "./dist/bin/verify-archive.js", "solanaut-prepare-policy": "./dist/bin/prepare-policy.js" },
  dependencies: source.dependencies,
};
writeFileSync(join(stage, "package.json"), JSON.stringify(manifest, null, 2) + "\n");
for (const name of ["replay", "pin-table", "verify-archive", "prepare-policy"]) {
  const path = join(stage, "dist/bin", name + ".js");
  writeFileSync(path, "#!/usr/bin/env node\n" + readFileSync(path, "utf8"));
  chmodSync(path, 0o755);
}
console.log("Private SDK candidate staged in .sandbox/releases/sdk");

packages/sdk/bin/replay.ts:
// Recompute every decision of a guard's record from its bytes, under a policy, and print the first
// that differs (ADR-010). Under the policy the record was written with, a sound record replays
// exactly; under another, this shows where that policy would have decided differently.
//
//   npm run replay -- <record.jsonl> <policy.json>
//
// The policy file is policy v1 as JSON, with amounts as decimal strings. Exit 0 if the record
// replays, 1 if it diverges, 2 if it cannot be read.

import { readFileSync } from "node:fs";
import { replay } from "../src/guard.ts";
import type { Entry } from "../src/log.ts";
import type { PolicyTrust } from "../src/signed-policy.ts";

const [recordPath, policyPath, trustPath, ...extra] = process.argv.slice(2);
if (!recordPath || !policyPath || extra.length > 0) {
  console.error("usage: npm run replay -- <record.jsonl> <policy.json|-> [public-trust.json]");
  process.exit(2);
}

let entries: Entry[];
let policy: unknown;
let trust: PolicyTrust | undefined;
try {
  entries = readFileSync(recordPath, "utf8").split("\n").filter(Boolean).map((line) => JSON.parse(line) as Entry);
  policy = policyPath === "-" ? undefined : JSON.parse(readFileSync(policyPath, "utf8"));
  trust = trustPath ? JSON.parse(readFileSync(trustPath, "utf8")) as PolicyTrust : undefined;
} catch (e) {
  console.error(`replay: ${(e as Error).message}`);
  process.exit(2);
}

const res = await replay(entries, policy, undefined, trust).catch((error: Error) => {
  console.error(`replay: ${error.message}`);
  process.exit(2);
});
if (res.ok) {
  console.log(`replays: ${entries.length} entries, ${res.decisions} decisions recomputed, no divergence`);
  process.exit(0);
}
const d = res.divergence!;
console.log(`diverges at seq ${d.seq}, field ${d.field}`);
console.log(`  recorded:   ${JSON.stringify(d.recorded)}`);
console.log(`  recomputed: ${JSON.stringify(d.recomputed)}`);
process.exit(1);

