// ADR-019: journal facts, not RPC actions. Count this helper in the signer's line budget.
import { encodeBase58 } from "./base58.ts";
import { decodeMessage, decodeTransaction } from "./message.ts";
import { verifyEd25519 } from "./latch.ts";
import type { DecisionEntry } from "./log.ts";

export type SigningEvent =
  | { stage: "signed"; decision: string; wire: string; signature: string }
  | { stage: "send-started"; decision: string; blockHeight: string }
  | { stage: "response"; decision: string; status: "denied" | "sent" | "uncertain"; signature?: string };
export interface SigningHistory {
  decision: DecisionEntry;
  signed?: Extract<SigningEvent, { stage: "signed" }>;
  started?: Extract<SigningEvent, { stage: "send-started" }>;
  response?: Extract<SigningEvent, { stage: "response" }>;
  redeemed?: true;
  settled?: true;
}

/** Validate before append and again during replay, without changing state. */
export function verifySigning(event: SigningEvent, history: SigningHistory | undefined, redeemed: boolean, policyHash: string): void {
  if (!history) throw new Error("signing event names no recorded request decision");
  const { decision: d, signed, started, response } = history;
  if (event.stage === "signed" && !d.allow) throw new Error("signing requires an allowed decision");
  if (response) throw new Error("request already has a durable response");
  if (history.settled && event.stage !== "response") throw new Error("the decision was already reported final");
  if (event.stage === "signed") {
    if (!redeemed) throw new Error("signing requires a durably redeemed receipt");
    if (signed) throw new Error("signed bytes already recorded");
    if (d.policyHash !== policyHash) throw new Error("signing under another policy is refused");
    if (typeof event.wire !== "string") throw new Error("signed wire must be canonical base64");
    const wire = Buffer.from(event.wire, "base64");
    if (wire.toString("base64") !== event.wire) throw new Error("signed wire must be canonical base64");
    let tx: ReturnType<typeof decodeTransaction>;
    try { tx = decodeTransaction(wire); } catch (error) { throw new Error(`invalid signed wire: ${(error as Error).message}`); }
    if (Buffer.from(tx.message).toString("base64") !== d.message) throw new Error("signed bytes differ from admission");
    const decoded = decodeMessage(tx.message);
    const sig = tx.signatures[0];
    if (tx.signatures.length !== 1 || !sig || encodeBase58(sig) !== event.signature || !verifyEd25519(decoded.staticAccounts[0]!, tx.message, sig)) throw new Error("signed wire signature does not verify");
  } else if (event.stage === "send-started") {
    if (!signed) throw new Error("send requires durably signed bytes");
    if (started) throw new Error("send already started; never resend");
    if (d.policyHash !== policyHash) throw new Error("send under another policy is refused");
    if (typeof event.blockHeight !== "string" || !/^(0|[1-9][0-9]*)$/.test(event.blockHeight)) throw new Error("invalid send block height");
    if (!d.expires || BigInt(event.blockHeight) > BigInt(d.expires.lastValidBlockHeight)) throw new Error("send receipt expired or has no bounded lifetime");
  } else if (event.stage === "response") {
    if (event.status === "denied") {
      if (d.allow || event.signature !== undefined) throw new Error("denied response requires a denied decision and no signature");
    } else if (event.status === "sent" || event.status === "uncertain") {
      if (!d.allow || !redeemed) throw new Error("send response requires an allowed redeemed decision");
      if (event.status === "sent" && !started) throw new Error("sent response requires send-started evidence");
      if (event.signature !== signed?.signature) throw new Error("response signature differs from signed evidence");
    } else throw new Error("unsupported signing response status");
  } else throw new Error("unsupported signing stage");
}

packages/sdk/src/state.ts:
// The guard's state, and the only way it changes: applying one entry of the record (ADR-010).
// Admission reads it; a restart rebuilds it by applying every entry again, in order.
//
//   reservations   what each allowed decision holds against the windows, until it ages out
//                  or an outcome releases it: "failed" releases the value but keeps the fees,
//                  which may have been paid; "expired" releases both; "unknown" releases nothing
//   intents        attempts at the same effects, so a second signature waits while an earlier
//                  one could still land (docs/SPEC.md §7)
//   latch          tripped by a run of denials or by REGROUND; released only by the operator
//   sensor         what the sensors remember of the proposal stream

import { createPolicy, type Policy } from "./policy.ts";
import type { ControlRequestEntry, ControlResponseEntry, DecisionEntry, Entry, Outcome } from "./log.ts";
import { verifyControlStart, verifyControlResponse } from "./control-request.ts";
import { RECENT, SENSOR_V1 } from "./sensor.ts";
import { parseReleaseText, verifyEd25519 } from "./latch.ts";
import { requestKey, verifyRequest } from "./request.ts";
import { verifySigning, type SigningHistory } from "./signing.ts";
import { copyAuthority } from "./authority.ts";

type Status = "pending" | Outcome;

export interface Attempt {
  decision: string;
  lastValidBlockHeight: bigint | null;
  status: Status;
}

export interface Intent {
  firstAt: number;
  attempts: Attempt[];
  /** An attempt landed: the intent is done. */
  done: boolean;
}

export interface Reservation {
  at: number;
  intentKey: string;
  sol: bigint;
  tokens: Map<string, bigint>;
  fees: bigint;
  valueReleased: boolean;
  feesReleased: boolean;
}

export interface GuardState {
  signing: Map<string, SigningHistory>;
  /** Full request history until the accepted disk index replaces in-memory retention. */
  requests: Map<string, DecisionEntry | ControlRequestEntry>;
  responses: Map<string, ControlResponseEntry>;
  /** During full restore/replay, retain entries needed by any recorded or incoming window. */
  retentionMs: number;
  seq: number;
  head: string;
  /** The latest time any entry carried. Windows are measured from here, so a clock that steps back cannot shrink them. */
  maxAt: number | null;
  consecutiveDenials: number;
  latched: { seq: number } | null;
  /** Allowed decisions still able to change state: reported on, redeemed, or counted. */
  allowed: Map<string, DecisionEntry>;
  reservations: Map<string, Reservation>;
  intents: Map<string, Intent>;
  redeemed: Set<string>;
  sensor: { recent: { intentKey: string; shape: string; fees: bigint; landed: boolean }[]; failureStreak: number; unknownStreak: number; lastAt: number | null; times: number[] };
}

export function initialState(): GuardState {
  return {
    signing: new Map(),
    requests: new Map(),
    responses: new Map(),
    retentionMs: 0,
    seq: 0,
    head: "",
    maxAt: null,
    consecutiveDenials: 0,
    latched: null,
    allowed: new Map(),
    reservations: new Map(),
    intents: new Map(),
    redeemed: new Set(),
    sensor: { recent: [], failureStreak: 0, unknownStreak: 0, lastAt: null, times: [] },
  };
}

const big = (s: string | null) => (s === null ? null : BigInt(s));

export function retentionWindow(entries: readonly Entry[], current: number): number {
  let window = current;
  for (const e of entries) if (e.kind === "policy") window = Math.max(window, createPolicy(JSON.parse(e.policy)).policy.windowMs);
  return window;
}

/** The effective time of a proposal at `at`: never earlier than anything already recorded. */
export const nowFor = (s: GuardState, at: number) => Math.max(at, s.maxAt ?? at);

/** An attempt that could still land: its outcome is not final, and no trusted height shows its blockhash expired. */
export function couldStillLand(a: Attempt, blockHeight: bigint | null): boolean {
  if (a.status !== "pending" && a.status !== "unknown") return false;
  return !(blockHeight !== null && a.lastValidBlockHeight !== null && blockHeight > a.lastValidBlockHeight);
}

/**
 * An attempt whose outcome nobody has reported as final. Past its last valid height it can no longer
 * land, but it may already have: until a report says which, it holds its intent (D14).
 */
export const unresolved = (a: Attempt): boolean => a.status === "pending" || a.status === "unknown";

/**
 * The live attempts at these effects, or null if the next allowed one starts a new intent. An
 * intent ends when an attempt lands, or once its window has passed since its first attempt with
 * nothing still able to land, so an exhausted intent is not blocked forever.
 */
export function currentIntent(s: GuardState, policy: Policy, intentKey: string, now: number, blockHeight: bigint | null): Intent | null {
  const i = s.intents.get(intentKey);
  if (!i || i.done) return null;
  if (now - i.firstAt >= policy.windowMs && !i.attempts.some((a) => couldStillLand(a, blockHeight))) return null;
  return i;
}

/**
 * What the window ending at `now` already holds. An attempt that a trusted height shows can still land stays counted
 * past the window, or a short window would admit a second payment beside it (D20).
 */
export function windowTotals(s: GuardState, policy: Policy, now: number, blockHeight: bigint | null = null) {
  let sol = 0n;
  let fees = 0n;
  const tokens = new Map<string, bigint>();
  const stillLanding = (hash: string, r: Reservation) => {
    if (blockHeight === null) return false;
    const a = s.intents.get(r.intentKey)?.attempts.find((x) => x.decision === hash);
    return a !== undefined && unresolved(a) && a.lastValidBlockHeight !== null && blockHeight <= a.lastValidBlockHeight;
  };
  for (const [hash, r] of s.reservations) {
    if (r.at <= now - policy.windowMs && !stillLanding(hash, r)) continue;
    if (!r.valueReleased) {
      sol += r.sol;
      for (const [mint, amount] of r.tokens) tokens.set(mint, (tokens.get(mint) ?? 0n) + amount);
    }
    if (!r.feesReleased) fees += r.fees;
  }
  return { sol, fees, tokens };
}

/** Apply one entry. Deterministic: the same entries, in the same order, give the same state. */
export function apply(s: GuardState, e: Entry, policy: Policy): void {
  if (e.v !== 1) throw new Error("unsupported record format version");
  if (e.kind === "decision") {
    if (e.source === "signer") { if (!e.deployment) throw new Error("signer authority is missing"); copyAuthority(e.deployment); }
    else if (e.deployment) throw new Error("caller decision cannot claim signer authority");
  }
  if (e.kind === "decision" && e.request) {
    verifyRequest(e, policy.latch.guardId);
    if (s.requests.has(requestKey(e.request))) throw new Error("duplicate recorded request identity");
  }
  if (e.kind === "request") verifyControlStart(e, policy.latch.guardId, s.requests);
  if (e.kind === "response") verifyControlResponse(e, s.requests, s.responses);
  if (e.seq !== s.seq || e.prev !== s.head) {
    throw new Error(`the record breaks at seq ${e.seq}: expected seq ${s.seq} after ${s.head || "the start"}`);
  }
  s.seq += 1;
  s.head = e.hash;
  s.maxAt = Math.max(s.maxAt ?? e.at, e.at);

  switch (e.kind) {
    case "request": s.requests.set(requestKey(e.request), e); return;
    case "response": s.responses.set(e.request, e); return;
    case "policy":
      return; // The guard verifies and selects it; this entry changes no admission state.
    case "decision": {
      if (e.request) s.signing.set(e.hash, { decision: e });
      if (e.request) s.requests.set(requestKey(e.request), e);
      if (e.intentKey !== null && e.shape !== null) {
        s.sensor.recent.push({ intentKey: e.intentKey, shape: e.shape, fees: BigInt(e.amounts?.fees ?? "0"), landed: false });
        if (s.sensor.recent.length > RECENT) s.sensor.recent.shift();
        s.sensor.lastAt = e.at;
        s.sensor.times.push(e.at);
        s.sensor.times = s.sensor.times.filter((t) => t > s.maxAt! - SENSOR_V1.minuteMs);
        if (!e.allow) s.sensor.failureStreak += 1;
      }
      if (e.allow && e.intentKey !== null && e.amounts !== null) {
        const blockHeight = big(e.blockHeight);
        let intent = currentIntent(s, policy, e.intentKey, nowFor(s, e.at), blockHeight);
        if (!intent) {
          intent = { firstAt: e.at, attempts: [], done: false };
          s.intents.set(e.intentKey, intent);
        }
        intent.attempts.push({ decision: e.hash, lastValidBlockHeight: big(e.lastValidBlockHeight), status: "pending" });
        s.reservations.set(e.hash, {
          at: e.at,
          intentKey: e.intentKey,
          sol: BigInt(e.amounts.sol),
          tokens: new Map(e.amounts.tokens.map((t) => [t.mint, BigInt(t.amount)])),
          fees: BigInt(e.amounts.fees),
          valueReleased: false,
          feesReleased: false,
        });
        s.allowed.set(e.hash, e);
      }
      s.consecutiveDenials = e.allow ? 0 : s.consecutiveDenials + 1;
      if (!s.latched && e.latch) s.latched = { seq: e.seq };
      prune(s, policy);
      return;
    }
    case "report": {
      if (e.outcome !== "unknown" && s.signing.has(e.decision)) s.signing.get(e.decision)!.settled = true;
      const r = s.reservations.get(e.decision);
      const attempt = r && s.intents.get(r.intentKey)?.attempts.find((a) => a.decision === e.decision);
      if (!r || !attempt) throw new Error(`report for ${e.decision}, which holds no reservation`);
      // An unknown outcome that becomes known stops counting as unknown.
      if (attempt.status === "unknown") s.sensor.unknownStreak = Math.max(0, s.sensor.unknownStreak - 1);
      attempt.status = e.outcome;
      if (e.outcome === "landed") {
        s.intents.get(r.intentKey)!.done = true;
        s.sensor.failureStreak = 0;
        s.sensor.unknownStreak = 0;
        for (const x of s.sensor.recent) if (x.intentKey === r.intentKey) x.landed = true;
      }
      if (e.outcome === "failed" || e.outcome === "expired") {
        r.valueReleased = true;
        if (e.outcome === "expired") r.feesReleased = true;
        s.sensor.failureStreak += 1;
      }
      if (e.outcome === "unknown") s.sensor.unknownStreak += 1;
      prune(s, policy);
      return;
    }
    case "release": {
      // Verified again, as the live guard verified it, so an edited record cannot release a latch (D17).
      const problem = releaseProblem(s, e, policy);
      if (problem) throw new Error(`the record's release at seq ${e.seq} does not verify: ${problem}`);
      // The operator has looked: start the stream over. The windows and intents stand.
      s.latched = null;
      s.consecutiveDenials = 0;
      s.sensor = { recent: [], failureStreak: 0, unknownStreak: 0, lastAt: s.sensor.lastAt, times: [] };
      return;
    }
    case "signing": {
      const h = s.signing.get(e.event.decision);
      verifySigning(e.event, h, h?.redeemed === true, createPolicy(policy).hash);
      if (e.event.stage === "signed") h!.signed = e.event;
      if (e.event.stage === "send-started") h!.started = e.event;
      if (e.event.stage === "response") h!.response = e.event;
      return;
    }
    case "redeem":
      s.redeemed.add(e.decision);
      if (s.signing.has(e.decision)) s.signing.get(e.decision)!.redeemed = true;
      return;
    default:
      throw new Error("unsupported record entry kind");
  }
}

/**
 * Why a recorded release does not hold, or null if it does: the latch it names, the guard and cluster, the expiry
 * against its own recorded time, and the release key's signature over its text. The policy hash in the text is bound
 * by the signature, and is not compared, since a record outlives a policy change.
 */
function releaseProblem(s: GuardState, e: Extract<Entry, { kind: "release" }>, policy: Policy): string | null {
  if (!s.latched) return "the guard was not latched";
  const f = parseReleaseText(e.text);
  if (!f) return "its text is not a release message";
  if (f.guardId !== policy.latch.guardId || f.cluster !== policy.latch.cluster) return "it names another guard or cluster";
  if (f.seq !== e.latchSeq || f.seq !== s.latched.seq) return `it releases the latch at seq ${f.seq}, and the guard latched at ${s.latched.seq}`;
  if (!(Date.parse(f.expires) > e.at)) return `it had expired at ${f.expires}`;
  let signature: Uint8Array;
  try {
    signature = new Uint8Array(Buffer.from(e.signature, "base64"));
  } catch {
    return "its signature is not base64";
  }
  if (!verifyEd25519(policy.latch.releaseKey, new TextEncoder().encode(e.text), signature)) return "the signature is not the release key's, over its text";
  return null;
}

/**
 * Forget what can no longer matter: reservations outside the window whose attempt is final, and
 * intents with nothing left to count or wait for. Driven only by recorded times, so a restore
 * prunes exactly as the live guard did.
 */
function prune(s: GuardState, policy: Policy): void {
  const horizon = (s.maxAt ?? 0) - Math.max(policy.windowMs, s.retentionMs);
  for (const [hash, r] of s.reservations) {
    if (r.at > horizon) continue;
    const intent = s.intents.get(r.intentKey);
    const attempt = intent?.attempts.find((a) => a.decision === hash);
    if (attempt && (attempt.status === "pending" || attempt.status === "unknown")) continue;
    s.reservations.delete(hash);
    s.allowed.delete(hash);
    s.redeemed.delete(hash);
  }
  for (const [key, intent] of s.intents) {
    const live = intent.attempts.some((a) => s.reservations.has(a.decision));
    if (!live && (intent.done || intent.firstAt <= horizon)) s.intents.delete(key);
  }
}

packages/sdk/src/tables.ts:
// Address lookup table accounts, read from their bytes, so an operator can pin a table's entries
// in the policy (ADR-009). A pin is the table's address and a prefix of its entries: tables are
// append-only and a closed table's address cannot be re-created, so a pinned prefix stays true
// (kb/sources/2026-09-30_anza-lookup-table-properties.md).
//
// Layout, from the address-lookup-table program: a 56-byte meta (u32 type, which is 1 for an
// initialized table; u64 deactivation slot; u64 last-extended slot; u8 start index; an optional
// 32-byte authority; padding), then 32 bytes per entry.

import { encodeBase58, isAddress } from "./base58.ts";
import type { PinnedTable } from "./message.ts";

const META_SIZE = 56;
const ACTIVE = 0xffffffffffffffffn;

export interface LookupTableState {
  entries: string[];
  /** u64::MAX while the table is active. */
  deactivationSlot: bigint;
  authority: string | null;
}

export function decodeLookupTableAccount(data: Uint8Array): LookupTableState {
  if (data.length < META_SIZE) throw new Error(`a lookup table account is at least ${META_SIZE} bytes; this one is shorter than that (${data.length})`);
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  const type = view.getUint32(0, true);
  if (type !== 1) throw new Error(`the account is not an initialized lookup table (type ${type})`);
  if ((data.length - META_SIZE) % 32 !== 0) throw new Error(`the entries are not a whole number of addresses (${data.length - META_SIZE} bytes)`);
  const deactivationSlot = view.getBigUint64(4, true);
  const hasAuthority = data[21] === 1;
  const entries: string[] = [];
  for (let o = META_SIZE; o < data.length; o += 32) entries.push(encodeBase58(data.subarray(o, o + 32)));
  return { entries, deactivationSlot, authority: hasAuthority ? encodeBase58(data.subarray(22, 54)) : null };
}

/** The pin for `policy.lookupTables`: every entry the table holds now. A table being closed is refused. */
export function pinFromAccount(address: string, data: Uint8Array): PinnedTable & { entries: string[] } {
  if (!isAddress(address)) throw new Error(`${JSON.stringify(address)} is not a base58 address`);
  const state = decodeLookupTableAccount(data);
  if (state.deactivationSlot !== ACTIVE) {
    throw new Error(`lookup table ${address} was deactivated at slot ${state.deactivationSlot}; pin an active table`);
  }
  return { address, entries: state.entries };
}

packages/sdk/test/adapters.test.ts:
// Milestone 2a.8, the adapters (docs/SPEC.md §8). guardedWallet wraps a Solana Agent Kit wallet:
// it exposes exactly BaseWallet's members (read first-hand from solana-agent-kit 2.0.10's types),
// never the wallet it wraps, and checks every transaction before the wallet sees it. After signing,
// the signed message must be the admitted one, signed by the wallet's key; anything else is
// stripped of its signatures and thrown. guardedSigner does the same for a @solana/kit partial
// signer. Both give the same verdicts as the SDK, and a denial is a typed SolanautDenied.

import { strict as assert } from "node:assert";
import { generateKeyPairSync } from "node:crypto";
import { test } from "node:test";
import {
  Keypair,
  PublicKey,
  SystemProgram,
  Transaction,
  TransactionInstruction,
  TransactionMessage,
  VersionedTransaction,
} from "@solana/web3.js";
import {
  appendTransactionMessageInstructions,
  compileTransaction,
  createKeyPairSignerFromBytes,
  createNoopSigner,
  createTransactionMessage,
  setTransactionMessageFeePayerSigner,
  setTransactionMessageLifetimeUsingBlockhash,
  type Address,
  type Blockhash,
} from "@solana/kit";
import { getTransferSolInstruction } from "@solana-program/system";
import { createGuard, type Guard } from "../src/guard.ts";
import { guardedWallet, type BaseWalletLike, type RpcLike } from "../src/adapters/agent-kit.ts";
import { guardedSigner } from "../src/adapters/kit.ts";
import { jsonRpc, RpcRefused } from "../src/adapters/rpc.ts";
import { createServer } from "node:http";
import { once } from "node:events";
import { SolanautDenied } from "../src/errors.ts";
import { encodeBase58 } from "../src/base58.ts";
import type { PolicyInput } from "../src/policy.ts";
import { PROGRAMS } from "../src/classify.ts";

const agent = Keypair.generate();
const treasury = Keypair.generate().publicKey;
const attacker = Keypair.generate().publicKey;
const MEMO = new PublicKey("MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr");
const LIGHTHOUSE = new PublicKey("L2TExMFKdjpN9kozasaurPirfHy9P8sbXoAN1qA3S95");
const operator = encodeBase58(Buffer.from(generateKeyPairSync("ed25519").publicKey.export({ format: "jwk" }).x!, "base64url"));

const policy = (principal = agent.publicKey.toBase58()): PolicyInput => ({
  version: 1,
  principal: [principal],
  programs: { allow: [PROGRAMS.system, PROGRAMS.memo], opaque: "deny" },
  destinations: { allow: [treasury.toBase58()] },
  sol: { maxPerTx: 1_000_000_000n, maxPerWindow: 3_000_000_000n },
  tokens: [],
  fees: { maxPriorityPerTx: 100_000n, maxPerWindow: 1_000_000_000n, tipAccounts: [] },
  lookupTables: [],
  windowMs: 60_000,
  intents: { maxAttempts: 3 },
  latch: { afterDenials: 100, releaseKey: operator, guardId: "adapters", cluster: "localnet" },
  messages: { allow: false },
  cosign: { allow: false },
  sensor: { expectedPerMinute: 60 },
});

/** Solana Agent Kit's KeypairWallet, as solana-agent-kit 2.0.10 builds it: it signs the caller's object in place. */
function keypairWallet(kp = agent, calls: string[] = []): BaseWalletLike {
  const sign = <T extends Transaction | VersionedTransaction>(tx: T): T => {
    if (tx instanceof VersionedTransaction) tx.sign([kp]);
    else tx.partialSign(kp);
    return tx;
  };
  return {
    publicKey: kp.publicKey,
    signTransaction: async (tx) => (calls.push("signTransaction"), sign(tx)),
    signAllTransactions: async (txs) => (calls.push("signAllTransactions"), txs.map(sign)),
    signAndSendTransaction: async () => { calls.push("signAndSendTransaction"); throw new Error("the guard must never ask the wallet to send"); },
    signMessage: async (m) => { calls.push("signMessage"); return m; },
  };
}

/** An RPC that records what it is sent, at a block height the test moves, and lands everything unless told otherwise. */
function fakeRpc(o: { refuse?: boolean; drop?: boolean; outcome?: "landed" | "failed" | "unknown"; statuses?: Map<string, "landed" | "failed" | "pending"> } = {}) {
  const sent: Uint8Array[] = [];
  const at = { height: 1_000n };
  const rpc: RpcLike = {
    getBlockHeight: async () => at.height,
    sendRawTransaction: async (wire) => {
      if (o.refuse) throw new RpcRefused("sendTransaction", "Transaction simulation failed: insufficient funds");
      // The request went out and no answer came back: the RPC may have forwarded the bytes.
      if (o.drop) throw new TypeError("fetch failed: other side closed");
      sent.push(wire);
      return encodeBase58(wire.subarray(1, 65));
    },
    confirm: async () => o.outcome ?? "landed",
    ...(o.statuses ? { getSignatureStatus: async (signature: string) => o.statuses!.get(signature) ?? null } : {}),
  };
  return { rpc, sent, at };
}

let blockhashSeed = 0;
const blockhash = () => encodeBase58(Uint8Array.from({ length: 32 }, (_, i) => (i * 7 + ++blockhashSeed) % 256));
const legacy = (...ixs: TransactionInstruction[]) => new Transaction({ feePayer: agent.publicKey, recentBlockhash: blockhash() }).add(...ixs);
const versioned = (...ixs: TransactionInstruction[]) =>
  new VersionedTransaction(new TransactionMessage({ payerKey: agent.publicKey, recentBlockhash: blockhash(), instructions: ixs }).compileToV0Message());
const pay = (to: PublicKey, lamports: number) => SystemProgram.transfer({ fromPubkey: agent.publicKey, toPubkey: to, lamports });

let clock = 1_000_000;
const now = () => (clock += 30_000);
const guard = () => createGuard({ policy: policy() });

async function rejectsWith(p: Promise<unknown>, rule: string) {
  await assert.rejects(p, (e: unknown) => {
    assert.ok(e instanceof SolanautDenied, `expected SolanautDenied, got ${(e as Error)?.name}: ${(e as Error)?.message}`);
    assert.equal(e.rule, rule, e.reason);
    return true;
  });
}

// --- the surface --------------------------------------------------------------------------------------

test("guardedWallet exposes exactly BaseWallet's members, frozen, and never the wallet it wraps", async () => {
  const inner = keypairWallet();
  const w = guardedWallet(inner, await guard(), { rpc: fakeRpc().rpc, now });
  assert.deepEqual(Object.keys(w).sort(), ["publicKey", "sendTransaction", "signAllTransactions", "signAndSendTransaction", "signMessage", "signTransaction"]);
  assert.ok(Object.isFrozen(w));
  assert.equal(w.publicKey, inner.publicKey);
  for (const v of Object.values(w)) assert.notEqual(v, inner, "no member is the wrapped wallet");
});

test("guardedWallet refuses a wallet whose key is outside the policy's principal, or no RPC to send through", async () => {
  const g = await guard();
  assert.throws(() => guardedWallet(keypairWallet(Keypair.generate()), g, { rpc: fakeRpc().rpc }), /principal/);
  assert.throws(() => guardedWallet(keypairWallet(), g, {} as never), /RPC/);
});

// --- signTransaction -----------------------------------------------------------------------------------

test("signTransaction: an allowed payment is signed by the wrapped wallet; a drain throws SolanautDenied before the wallet is asked", async () => {
  const calls: string[] = [];
  const w = guardedWallet(keypairWallet(agent, calls), await guard(), { rpc: fakeRpc().rpc, now });
  const ok = await w.signTransaction(legacy(pay(treasury, 1_000)));
  assert.ok(ok.verifySignatures(), "signed by the agent's key");
  assert.deepEqual(calls, ["signTransaction"]);
  const drain = legacy(pay(attacker, 1_000));
  await assert.rejects(w.signTransaction(drain), (e: unknown) => {
    assert.ok(e instanceof SolanautDenied);
    assert.equal(e.rule, "destination-not-allowed");
    assert.match(e.reason, /not an allowed destination/);
    assert.equal(e.decision?.allow, false);
    return true;
  });
  assert.deepEqual(calls, ["signTransaction"], "the wallet never saw the drain");
  assert.ok(drain.signatures.every((s) => s.signature === null));
});

test("the adapters give the same verdicts as the SDK, for legacy and v0 transactions", async () => {
  const nonce = Keypair.generate().publicKey;
  const cases: [string, TransactionInstruction[]][] = [
    ["a payment", [pay(treasury, 5_000)]],
    ["a drain", [pay(attacker, 5_000)]],
    ["over the cap", [pay(treasury, 2_000_000_000)]],
    ["a durable nonce", [SystemProgram.nonceAdvance({ noncePubkey: nonce, authorizedPubkey: agent.publicKey }), pay(treasury, 1)]],
    ["an unlisted program", [new TransactionInstruction({ programId: LIGHTHOUSE, keys: [], data: Buffer.from([1]) })]],
    ["a memo and a payment", [new TransactionInstruction({ programId: MEMO, keys: [], data: Buffer.from("invoice") }), pay(treasury, 7)]],
  ];
  for (const build of [legacy, versioned]) {
    for (const [label, ixs] of cases) {
      const sdk = await guard();
      const at = now();
      const tx = build(...ixs);
      const message = tx instanceof VersionedTransaction ? tx.message.serialize() : tx.serializeMessage();
      const expected = sdk.check({ message: new Uint8Array(message), at, blockHeight: 1_000n, lastValidBlockHeight: 1_150n });
      const w = guardedWallet(keypairWallet(), await guard(), { rpc: fakeRpc().rpc, now: () => at });
      let got: string;
      try {
        await w.signTransaction(tx);
        got = "allow";
      } catch (e) {
        got = (e as SolanautDenied).rule;
      }
      assert.equal(got, expected.allow ? "allow" : expected.rule, `${build.name}: ${label}`);
    }
  }
});

