  const unlisted = { programAddress: UNLISTED_PROGRAM, accounts: [], data: Uint8Array.of(1) } as Instruction;
  const opaque = { programAddress: OPAQUE, accounts: [], data: Uint8Array.of(1) } as Instruction;
