  assert.equal(retry.telemetry?.repetition, 1, "the second payment has not landed: this one retries it");
});

packages/sdk/test/latch-c.test.ts:
// ADR-012 option C, RT-3: predecessor means the previous decision in the record,
// including after restore, rather than the last entry or transient controller state.

import { strict as assert } from "node:assert";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { createGuard, replay, type Decision, type GuardOptions } from "../src/guard.ts";
import { seal, type Entry } from "../src/log.ts";
import { craftLegacy, key } from "./support/craft.ts";
import { WORKLOAD_POLICY } from "./support/workload.ts";
import { latchCases } from "./support/latch-streams.ts";

const hostile: GuardOptions["sensor"] = () => ({ intensity: 1, valence: -1, repetition: 1 });
const quiet: GuardOptions["sensor"] = () => ({ intensity: 0, valence: 0, repetition: 0 });
const policy = { ...WORKLOAD_POLICY, latch: { ...WORKLOAD_POLICY.latch, afterDenials: 100 } };
const message = (to = 3, amount = 1n) => craftLegacy({
  header: [1, 0, 1], keys: [key(1), key(to), key(0)],
  instructions: [{ program: 2, accounts: [0, 1], data: [2, 0, 0, 0, ...Array.from({ length: 8 }, (_, i) => Number((amount >> BigInt(8 * i)) & 255n))] }],
});
const proposal = (turn: number, to = 3) => ({ message: message(to), at: 1_000_000 + turn * 400 });
const regroundDenial = (d: Decision) => {
  assert.equal(d.allow, false);
  assert.equal(d.rule, "destination-not-allowed");
  assert.equal(d.posture, "REGROUND");
};

test("LAT-1 / RT-3: a single REGROUND denial by an earlier rule does not latch", async () => {
  const g = await createGuard({ policy, sensor: hostile });
  try {
    assert.equal(g.check(proposal(0)).posture, "INHIBIT");
    const d = g.check(proposal(1));
    regroundDenial(d);
    assert.equal(d.latch, undefined);
    assert.equal(g.status().latched, false);
  } finally { g.close(); }
});

test("LAT-2 / RT-3: two consecutive REGROUND denials latch, across report and restart", async () => {
  const dir = mkdtempSync(join(tmpdir(), "solanaut-latch-"));
  const log = join(dir, "record.jsonl");
  let g = await createGuard({ policy, sensor: hostile, log });
  try {
    const first = g.check(proposal(0, 2));
    assert.equal(first.allow, true);
    const denied = g.check(proposal(1));
    regroundDenial(denied);
    assert.equal(g.status().latched, false);
    g.report(first.hash, "failed");
    g.close();
    g = await createGuard({ policy, sensor: hostile, log });
    assert.equal(g.status().latched, false);
    const again = g.check(proposal(2));
    regroundDenial(again);
    assert.equal(again.latch, true);
    assert.equal(g.status().latched, true);
    assert.equal((await replay(g.entries(), policy, hostile)).ok, true);
  } finally { g.close(); rmSync(dir, { recursive: true, force: true }); }
});

test("LAT-2 / RT-3: a decision without REGROUND breaks the consecutive pair", async () => {
  const g = await createGuard({ policy, sensor: hostile });
  try {
    g.check(proposal(0));
    regroundDenial(g.check(proposal(1)));
    const malformed = g.check({ message: Uint8Array.of(1), at: 1_001_000 });
    assert.equal(malformed.rule, "malformed-proposal");
    assert.equal(malformed.posture, null);
    const separated = g.check(proposal(3));
    regroundDenial(separated);
    assert.equal(separated.latch, undefined);
    const consecutive = g.check(proposal(4));
    regroundDenial(consecutive);
    assert.equal(consecutive.latch, true);
  } finally { g.close(); }
});

test("LAT-3 / RT-3: Keel's own loop denial latches immediately", async () => {
  const g = await createGuard({ policy, sensor: hostile });
  try {
    const first = g.check(proposal(0, 2));
    assert.equal(first.allow, true);
    g.report(first.hash, "landed");
    const d = g.check(proposal(1, 2));
    assert.equal(d.rule, "loop-reground");
    assert.equal(d.latch, true);
  } finally { g.close(); }
});

test("LAT-4 / RT-3: the policy's consecutive-denial threshold still latches without REGROUND", async () => {
  const g = await createGuard({ policy: { ...policy, latch: { ...policy.latch, afterDenials: 3 } }, sensor: quiet });
  try {
    for (let i = 0; i < 2; i++) assert.equal(g.check(proposal(i)).latch, undefined);
    const d = g.check(proposal(2));
    assert.equal(d.posture, "DEFAULT");
    assert.equal(d.rule, "destination-not-allowed");
    assert.equal(d.latch, true);
  } finally { g.close(); }
});

test("LAT-5 / RT-3: replay names the accepted one-time divergence of a V0 latch", async () => {
  const g = await createGuard({ policy, sensor: hostile });
  try {
    g.check(proposal(0));
    regroundDenial(g.check(proposal(1)));
    const entries = g.entries().map((e): Entry => {
      if (e.kind !== "decision" || e.seq !== 1) return e;
      const { hash: _hash, ...body } = e;
      return seal<Decision>({ ...body, latch: true });
    });
    const res = await replay(entries, policy, hostile);
    assert.equal(res.ok, false);
    assert.equal(res.divergence?.seq, 1);
    assert.equal(res.divergence?.field, "latch");
  } finally { g.close(); }
});

for (const [label, run, latchTurn, allowed, legitStopped] of latchCases) {
  test(`LAT-6 / RT-3: option C reproduces the archived stream: ${label}`, async () => {
    const x = await run();
    try {
      assert.deepEqual(x.summary(), { latchTurn, allowed, legitStopped });
      if (label.startsWith("drain storm")) assert.ok(x.ds.every((d) => !d.allow));
      assert.equal((await replay(x.g.entries(), x.g.policy)).ok, true);
    } finally { x.g.close(); }
  });
}

packages/sdk/test/ownership.test.ts:
// OWN: safe SDK stale-lock refusal and kernel-held ownership across processes.
import { strict as assert } from "node:assert";
import { spawn, spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { hostname, tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { fileStore } from "../src/record.ts";

const record = () => join(mkdtempSync(join(tmpdir(), "solanaut-ownership-")), "guard.jsonl");
test("OWN-1: SDK refuses stale ownership instead of removing the lock", () => {
  const path = record();
  const dead = spawnSync(process.execPath, ["-e", "process.stdout.write(String(process.pid))"], { encoding: "utf8" });
  const marker = JSON.stringify({ pid: Number(dead.stdout), host: hostname(), at: 0 });
  writeFileSync(path + ".lock", marker);
  assert.throws(() => fileStore(path), /stale|locked/);
  assert.equal(readFileSync(path + ".lock", "utf8"), marker);
});
test("OWN-2: kernel lock outlives its acquisition helper, excludes other writers and preserves its inode on close", () => {
  const path = record();
  const owner = fileStore(path, { ownership: "kernel" });
  assert.throws(() => fileStore(path, { ownership: "kernel" }), /locked/);
  assert.throws(() => fileStore(path), /locked/);
  owner.close();
  assert.equal(existsSync(path + ".lock"), true, "a kernel mutex inode must never be unlinked on close");
  const reopened = fileStore(path, { ownership: "kernel" });
  reopened.close();
  assert.throws(() => fileStore(path), /kernel|locked|stale/);
});
test("OWN-2: a crashed kernel owner releases ownership and competing restarts admit exactly one writer", async () => {
  const path = record();
  const owner = spawn(process.execPath, ["packages/sdk/test/support/ownership-child.ts", path], { stdio: ["ignore", "pipe", "pipe"] });
  const ready = new Promise<void>((resolve, reject) => {
    owner.stdout.once("data", () => resolve());
    owner.once("exit", (code) => reject(new Error(`owner exited before readiness: ${code}`)));
  });
  await ready;
  const gone = new Promise((resolve) => owner.once("exit", resolve));
  owner.kill("SIGKILL"); await gone;
  const contenders = Array.from({ length: 8 }, () => spawn(process.execPath, ["packages/sdk/test/support/ownership-child.ts", path], { stdio: ["ignore", "pipe", "pipe"] }));
  try {
    const results = await Promise.all(contenders.map((child) => new Promise<string>((resolve) => {
      child.stdout.once("data", () => resolve("owner"));
      child.once("exit", (code) => resolve(code === 1 ? "locked" : `exit:${code}`));
    })));
    assert.equal(results.filter((r) => r === "owner").length, 1, JSON.stringify(results));
    assert.equal(results.filter((r) => r === "locked").length, 7, JSON.stringify(results));
  } finally {
    await Promise.all(contenders.filter((child) => child.exitCode === null && child.signalCode === null).map((child) => new Promise((resolve) => { child.once("exit", resolve); child.kill("SIGKILL"); })));
  }
});
test("OWN-3: established protected records are not recreated if missing", () => {
  const path = record();
  assert.throws(() => fileStore(path, { ownership: "kernel", create: false }), /ENOENT/);
  assert.equal(existsSync(path), false);
  const initial = fileStore(path, { ownership: "kernel" }); initial.close();
  const existing = fileStore(path, { ownership: "kernel", create: false }); existing.close();
});

packages/sdk/test/pin-table.test.ts:
// The pin command end to end, against a local stand-in for the RPC: it asks at finalized
// commitment, refuses an account the lookup table program does not own, and prints the pin.

import { strict as assert } from "node:assert";
import { execFile } from "node:child_process";
import { createServer } from "node:http";
import { once } from "node:events";
import { test } from "node:test";
import { promisify } from "node:util";
import { getAddressDecoder } from "@solana/kit";
import { craftTableAccount, key } from "./support/craft.ts";

const run = promisify(execFile);
const b58 = (k: number[]) => getAddressDecoder().decode(Uint8Array.from(k)) as string;
const TABLE = b58(key(50));

async function rpc(answer: (params: unknown[]) => unknown) {
  const seen: unknown[] = [];
  const server = createServer(async (req, res) => {
    let raw = "";
    for await (const chunk of req) raw += chunk;
    const call = JSON.parse(raw);
    seen.push(call);
    res.setHeader("content-type", "application/json");
    res.end(JSON.stringify({ jsonrpc: "2.0", id: call.id, result: { context: { slot: 1 }, value: answer(call.params) } }));
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const { port } = server.address() as { port: number };
  return { url: `http://127.0.0.1:${port}`, seen, close: () => server.close() };
}

const pinTable = (...args: string[]) => run("node", ["packages/sdk/bin/pin-table.ts", ...args]);

test("pin-table prints the table's address and entries, read at finalized commitment", async () => {
  const data = Buffer.from(craftTableAccount({ entries: [key(3), key(4)] })).toString("base64");
  const s = await rpc(() => ({ owner: "AddressLookupTab1e1111111111111111111111111", data: [data, "base64"], lamports: 1, executable: false }));
  try {
    const { stdout } = await pinTable("--url", s.url, TABLE);
    assert.deepEqual(JSON.parse(stdout), { address: TABLE, entries: [b58(key(3)), b58(key(4))] });
    assert.deepEqual((s.seen[0] as { params: unknown[] }).params, [TABLE, { encoding: "base64", commitment: "finalized" }]);
  } finally {
    s.close();
  }
});

test("pin-table refuses: no --url, an account another program owns, no account, a deactivated table", async () => {
  await assert.rejects(pinTable(TABLE), (e: { code: number; stderr: string }) => e.code === 2 && /--url is required/.test(e.stderr));

  const data = Buffer.from(craftTableAccount({ entries: [key(3)] })).toString("base64");
  const cases: [unknown, RegExp][] = [
    [{ owner: "11111111111111111111111111111111", data: [data, "base64"] }, /not the lookup table program/],
    [null, /no account/],
    [{ owner: "AddressLookupTab1e1111111111111111111111111", data: [Buffer.from(craftTableAccount({ entries: [key(3)], deactivationSlot: 7n })).toString("base64"), "base64"] }, /deactivated/],
  ];
  for (const [value, why] of cases) {
    const s = await rpc(() => value);
    try {
      await assert.rejects(pinTable("--url", s.url, TABLE), (e: { code: number; stderr: string }) => e.code === 2 && why.test(e.stderr));
    } finally {
      s.close();
    }
  }
});

packages/sdk/test/policy.test.ts:
// Milestone 2a.4, policy v1 (docs/SPEC.md §3 and rule 0). A policy is validated when it is
// created, or no guard exists; it is copied, frozen all the way down, and hashed. Amounts are
// bigint, so nothing is lost above 2^53. Closes defects D1 (a mutable policy), D2 (an unvalidated
// policy: NaN disabled a cap) and D9 (lamports as JS numbers).

import { strict as assert } from "node:assert";
import { test } from "node:test";
import { contextOf, createPolicy, PolicyError, type PolicyInput } from "../src/policy.ts";
import { randomAddress, rng } from "./support/kit.ts";

const r = rng(404);
const addr = () => randomAddress(r) as string;
const AGENT = addr(), OPERATOR = addr(), TREASURY = addr(), USDC = addr(), TABLE = addr(), ENTRY = addr(), TIP = addr();
const SYSTEM = "11111111111111111111111111111111";

const valid = (): PolicyInput => ({
  version: 1,
  principal: [AGENT],
  programs: { allow: [SYSTEM], opaque: "deny" },
  destinations: { allow: [TREASURY] },
  sol: { maxPerTx: 1_000_000_000n, maxPerWindow: 3_000_000_000n },
  tokens: [{ mint: USDC, program: "token", maxPerTx: "5000000", maxPerWindow: "20000000" }],
  fees: { maxPriorityPerTx: 100_000n, maxPerWindow: 1_000_000n, tipAccounts: [TIP] },
  lookupTables: [{ address: TABLE, entries: [ENTRY] }],
  windowMs: 86_400_000,
  intents: { maxAttempts: 3 },
  latch: { afterDenials: 5, releaseKey: OPERATOR, guardId: "agent-1", cluster: "devnet" },
  messages: { allow: false },
  cosign: { allow: false },
  sensor: { expectedPerMinute: 2 },
});

/** A valid policy with one field replaced, by path. */
function withField(path: string, value: unknown): unknown {
  const p: any = valid();
  const keys = path.split(".");
  let o = p;
  for (const k of keys.slice(0, -1)) o = o[k];
  if (value === DELETE) delete o[keys.at(-1)!];
  else o[keys.at(-1)!] = value;
  return p;
}
const DELETE = Symbol("delete");

function invalid(input: unknown, mentions: RegExp, label: string) {
  assert.throws(() => createPolicy(input), (e: unknown) => {
    assert.ok(e instanceof PolicyError, `${label}: expected a PolicyError, got ${(e as Error)?.name}: ${(e as Error)?.message}`);
    assert.equal(e.rule, "invalid-policy");
    assert.match(e.message, mentions, `${label}: ${e.message}`);
    return true;
  }, label);
}

test("a valid policy loads, with amounts as bigint and a 64-hex hash", () => {
  const { policy, hash } = createPolicy(valid());
  assert.equal(policy.sol.maxPerTx, 1_000_000_000n);
  assert.equal(policy.tokens[0]!.maxPerTx, 5_000_000n, "a decimal string becomes a bigint");
  assert.match(hash, /^[0-9a-f]{64}$/);
});

test("the hash depends on content only: key order and amount spelling do not change it; any value does", () => {
  const { hash } = createPolicy(valid());
  const reordered = Object.fromEntries(Object.entries(valid()).reverse());
  assert.equal(createPolicy(reordered).hash, hash, "key order");
  assert.equal(createPolicy(withField("sol.maxPerTx", "1000000000")).hash, hash, "a bigint and its decimal string");
  for (const [path, value] of [
    ["sol.maxPerTx", 1_000_000_001n],
    ["windowMs", 86_400_001],
    ["latch.guardId", "agent-2"],
    ["programs.opaque", "allow"],
    ["principal", [AGENT, TREASURY]],
  ] as const) {
    assert.notEqual(createPolicy(withField(path, value)).hash, hash, path);
  }
});

test("the hash is SHA-256 of canonical JSON: sorted keys, no whitespace, amounts as decimal strings", () => {
  // The expected digest was computed outside this codebase, by Python's
  // json.dumps(policy, sort_keys=True, separators=(",", ":")) over the same policy with amounts as strings.
  const { hash } = createPolicy({
    version: 1,
    principal: ["MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr"],
    programs: { allow: ["11111111111111111111111111111111"], opaque: "deny" },
    destinations: { allow: ["TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA"] },
    sol: { maxPerTx: 1_000_000_000n, maxPerWindow: 3_000_000_000n },
    tokens: [{ mint: "ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL", program: "token", maxPerTx: 5n, maxPerWindow: 10n }],
    fees: { maxPriorityPerTx: 100_000n, maxPerWindow: 1_000_000n, tipAccounts: ["ComputeBudget111111111111111111111111111111"] },
    lookupTables: [],
    windowMs: 86_400_000,
    intents: { maxAttempts: 3 },
    latch: { afterDenials: 5, releaseKey: "Memo1UhkJRfHyvLMcVucJwxXeuD728EqVDDwQDxFMNo", guardId: "known-answer", cluster: "devnet" },
    messages: { allow: false },
    cosign: { allow: false },
    sensor: { expectedPerMinute: 2 },
  });
  assert.equal(hash, "8df52fd7623cdd1a19226200df07b4003b2f427d295eb2748d0f2b548840caf4");
});

test("D1: the policy is a frozen copy; neither the caller's object nor the returned one can widen it", () => {
  const input: any = valid();
  const { policy, hash } = createPolicy(input);
  input.destinations.allow.push("attacker");
  input.sol.maxPerTx = 10n ** 30n;
  assert.deepEqual(policy.destinations.allow, [TREASURY], "changing the input changes nothing");
  assert.equal(policy.sol.maxPerTx, 1_000_000_000n);
  assert.throws(() => (policy.destinations.allow as string[]).push("attacker"), TypeError);
  assert.throws(() => { (policy.sol as any).maxPerTx = 1n; }, TypeError);
  assert.throws(() => { (policy.lookupTables[0]!.entries as string[])[0] = "attacker"; }, TypeError);
  assert.throws(() => { (policy as any).principal = []; }, TypeError);
  assert.equal(createPolicy(valid()).hash, hash);
});

test("D2: a cap that is not a whole, non-negative amount is refused, never read as no cap", () => {
  for (const bad of [Number.NaN, Infinity, -1, 1.5, 1e9, "1.5", "-1", "01", "", " 1", "1e9", "0x10", null, undefined, true]) {
    invalid(withField("sol.maxPerTx", bad), /sol\.maxPerTx/, `sol.maxPerTx = ${String(bad)}`);
  }
  invalid(withField("fees.maxPerWindow", Number.NaN), /fees\.maxPerWindow/, "fees");
  invalid(withField("tokens", [{ mint: USDC, program: "token", maxPerTx: -5n, maxPerWindow: 1n }]), /tokens\[0\]\.maxPerTx/, "token cap");
  assert.equal(createPolicy(withField("sol.maxPerTx", 0n)).policy.sol.maxPerTx, 0n, "zero is a cap: nothing may move");
});

test("D9: amounts past 2^53 are exact", () => {
  const max = 18_446_744_073_709_551_615n;
  const { policy } = createPolicy(withField("sol.maxPerWindow", max.toString()));
  assert.equal(policy.sol.maxPerWindow, max);
  invalid(withField("sol.maxPerWindow", (max + 1n).toString()), /sol\.maxPerWindow/, "past u64");
});

test("rule 0: addresses must be canonical base58 keys, and the principal must hold one", () => {
  invalid(withField("principal", []), /principal/, "empty principal");
  for (const [path, value] of [
    ["principal", ["not-an-address"]],
    ["principal", [""]],
    ["destinations.allow", [TREASURY, "0OIl"]],
    ["programs.allow", ["x"]],
    ["fees.tipAccounts", ["tip"]],
    ["latch.releaseKey", "operator"],
    ["tokens", [{ mint: "usdc", program: "token", maxPerTx: 1n, maxPerWindow: 1n }]],
    ["lookupTables", [{ address: "table", entries: [] }]],
    ["lookupTables", [{ address: TABLE, entries: [ENTRY, "not-a-key"] }]],
  ] as const) {
    invalid(withField(path, value), new RegExp(path.split(".")[0]!), `${path} = ${JSON.stringify(value, (_k, x) => (typeof x === "bigint" ? `${x}n` : x))}`);
  }
});

test("rule 0: the latch's release key is never a principal key, so the agent cannot release its own latch", () => {
  invalid(withField("latch.releaseKey", AGENT), /releaseKey/, "the agent's key");
});

test("rule 0: one entry per mint and per table, a known token program, and a known cluster", () => {
  invalid(withField("tokens", [valid().tokens[0], valid().tokens[0]]), /tokens/, "a mint twice");
  invalid(withField("lookupTables", [{ address: TABLE, entries: [] }, { address: TABLE, entries: [ENTRY] }]), /lookupTables/, "a table twice");
  invalid(withField("tokens", [{ mint: USDC, program: "token-2023", maxPerTx: 1n, maxPerWindow: 1n }]), /program/, "token program");
  invalid(withField("latch.cluster", "mainnet"), /cluster/, "cluster");
  invalid(withField("programs.opaque", "maybe"), /opaque/, "opaque");
});

test("rule 0: counts and durations are positive whole numbers; the guard id fits on one line", () => {
  for (const [path, bad] of [
    ["windowMs", 0], ["windowMs", -1], ["windowMs", Number.NaN], ["windowMs", 1.5],
    ["intents.maxAttempts", 0], ["latch.afterDenials", 0], ["latch.afterDenials", 2.5],
    ["sensor.expectedPerMinute", 0], ["sensor.expectedPerMinute", Number.NaN],
    ["latch.guardId", ""], ["latch.guardId", "a\nb"], ["latch.guardId", "x".repeat(65)],
  ] as const) {
    invalid(withField(path, bad), new RegExp(path.split(".").at(-1)!), `${path} = ${String(bad)}`);
  }
});

test("rule 0: v1 never signs messages or co-signs, and refuses any field it does not know", () => {
  invalid(withField("messages.allow", true), /messages/, "messages");
  invalid(withField("cosign.allow", true), /cosign/, "cosign");
  invalid(withField("version", 2), /version/, "version");
  invalid({ ...(valid() as object), maxLamportsPerTx: 1 }, /maxLamportsPerTx/, "an unknown field, say a v0 one");
  invalid(withField("sol.maxPertx", 1n), /maxPertx/, "a misspelt field");
  invalid(withField("fees", DELETE), /fees/, "a missing section");
  invalid(null, /policy/, "null");
  invalid("{}", /policy/, "a string");
});

test("every problem is reported at once, so an operator fixes them in one pass", () => {
  const p: any = valid();
  p.principal = [];
  p.windowMs = 0;
  p.sol.maxPerTx = Number.NaN;
  assert.throws(() => createPolicy(p), (e: unknown) => e instanceof PolicyError && e.problems.length === 3);
});

test("the classifier's context comes from the policy", () => {
  const { policy } = createPolicy(valid());
  assert.deepEqual(contextOf(policy), {
    principal: [AGENT],
    destinations: [TREASURY],
    tokens: [{ mint: USDC, program: "token" }],
    tipAccounts: [TIP],
    lookupTables: [{ address: TABLE, entries: [ENTRY] }],
  });
});

// LIF-1: an identity is committed with its admission, including denials.
import { strict as assert } from "node:assert";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { createGuard, replay, type Guard } from "../src/guard.ts";
import { seal, type DecisionEntry } from "../src/log.ts";
import { WORKLOAD_POLICY } from "./support/workload.ts";
import { craftLegacy, key } from "./support/craft.ts";

const message = (destination = 2, amount = 1) => craftLegacy({ header: [1, 0, 1], keys: [key(1), key(destination), key(0)], instructions: [{ program: 2, accounts: [0, 1], data: [2, 0, 0, 0, amount, 0, 0, 0, 0, 0, 0, 0] }] });
const id = { clientId: "agent-a", id: "request-a" };
// Test against the old API first without changing the production signature.
const check = (g: Guard, bytes: Uint8Array, at: number, identity = id, intent?: string) =>
  (g.check as (p: { message: Uint8Array; at: number; intent?: string }, request: typeof id) => DecisionEntry)({ message: bytes, at, ...(intent === undefined ? {} : { intent }) }, identity);

test("LIF-1: duplicate admission returns the original entry without another reservation or controller tick", async () => {
  const g = await createGuard({ policy: WORKLOAD_POLICY });
  try {
    const d = check(g, message(), 1000);
    assert.equal(d.allow, true); assert.ok(d.request);
    assert.equal(check(g, message(), 2000), d);
    assert.equal(g.entries().length, 1); assert.equal(g.status().seq, 1);
    assert.equal(g.redeem(message(), d.hash).ok, true);
    assert.equal(check(g, message(), 3000), d);
    assert.equal(g.redeem(message(), d.hash).ok, false, "retry returns no fresh receipt");
  } finally { g.close(); }
});
test("LIF-1: duplicate denied request returns the same denial without accumulating latch denials", async () => {
  const g = await createGuard({ policy: WORKLOAD_POLICY });
  try {
    const d = check(g, message(3), 1000);
    assert.equal(d.rule, "destination-not-allowed");
    assert.equal(check(g, message(3), 2000), d);
    assert.equal(g.status().consecutiveDenials, 1);
  } finally { g.close(); }
});
test("LIF-1: changed bytes or grouping under the same identity are refused", async () => {
  const g = await createGuard({ policy: WORKLOAD_POLICY });
  try {
    check(g, message(), 1000, id, "group-a");
    for (const [bytes, intent] of [[message(2, 2), "group-a"], [message(), "group-b"]] as const) {
      const d = check(g, bytes, 2000, id, intent);
      assert.equal(d.allow, false); assert.match(d.reason, /identity.*payload/);
    }
    assert.equal(g.entries().length, 1);
  } finally { g.close(); }
});
test("LIF-1: client identities are separate namespaces and invalid identities fail closed", async () => {
  const g = await createGuard({ policy: WORKLOAD_POLICY });
  try {
    check(g, message(3), 1000);
    assert.equal(check(g, message(3), 2000, { ...id, clientId: "agent-b" }).seq, 1);
    for (const invalid of [{ ...id, id: "" }, { ...id, clientId: "x".repeat(129) }]) assert.equal(check(g, message(), 3000, invalid).allow, false);
    assert.equal(g.entries().length, 2);
  } finally { g.close(); }
});
test("LIF-1: identity and original decision survive durable restart", async () => {
  const path = join(mkdtempSync(join(tmpdir(), "solanaut-request-")), "guard.jsonl");
  const g = await createGuard({ policy: WORKLOAD_POLICY, log: path });
  const d = check(g, message(), 1000); g.close();
  const next = await createGuard({ policy: WORKLOAD_POLICY, log: path });
  try {
    assert.equal(check(next, message(), 9000).hash, d.hash);
    assert.equal(next.entries().length, 1);
    assert.equal((await replay(next.entries(), WORKLOAD_POLICY)).ok, true);
  } finally { next.close(); }
});
for (const fault of ["digest", "guard", "duplicate"]) test(`LIF-1: resealed ${fault} request evidence refuses restore and replay`, async () => {
  const g = await createGuard({ policy: WORKLOAD_POLICY });
  const d = check(g, message(), 1000); g.close();
  assert.ok(d.request);
  const { hash: _hash, ...body } = d;
  const entries = fault === "duplicate" ? [d, seal<DecisionEntry>({ ...body, seq: 1, prev: d.hash })] :
    [seal<DecisionEntry>({ ...body, request: { ...d.request, ...(fault === "digest" ? { digest: "0".repeat(64) } : { guardId: "foreign" }) } })];
  await assert.rejects(createGuard({ policy: WORKLOAD_POLICY, log: { entries, append() {}, close() {} } }), /request/);
  assert.equal((await replay(entries, WORKLOAD_POLICY)).ok, false);
});

