    (e: Entry) => ({ ...e, v: 2 }),
    (e: Entry) => ({ ...e, profile: { invented: true } }),
    (e: Entry) => ({ ...e, signature: Buffer.alloc(64).toString("base64") }),
    (e: Entry) => ({ ...e, policy: canonicalJSON({ ...policy, sol: { ...policy.sol, maxPerTx: 2n } }) }),
